    const __m256 z0_vh = _mm256_add_ps(z0_sh, z0_c);
    const __m256 z0_vh_z = _mm256_sub_ps(z0_vh, z0_sh);
    const __m256 z0_vl = _mm256_sub_ps(z0_c, z0_vh_z);
    const __m256 z0_w = _mm256_add_ps(z0_tl, z0_vl);
