    const __m256 l0_t_s_ab = _mm256_andnot_ps(_mm256_set1_ps(-0.0f), l0_nz);
    const __m256 l0_t_s_m = _mm256_cmp_ps(l0_t_s_aa, l0_t_s_ab, _CMP_LT_OQ);
    const __m256 l0_t_s_h = _mm256_blendv_ps(l0_dd, l0_nz, l0_t_s_m);
    const __m256 l0_t_s_l = _mm256_blendv_ps(l0_nz, l0_dd, l0_t_s_m);
