    const __m256d mu = _mm256_or_pd(mu_h, mu_t);
    const __m256d zu0 = _mm256_blendv_pd(xu0, yu0, mu);
    const __m256d zu1 = _mm256_blendv_pd(xu1, yu1, mu);
    zl0_out = zl0;
    zl1_out = zl1;
    zu0_out = zu0;
    zu1_out = zu1;
