    const __m256 zb0_t = _mm256_fmadd_ps(zb0_az, _mm256_set1_ps(0x1.800008p-47f), _mm256_setzero_ps());
    const __m256 eb = _mm256_fmadd_ps(zb0_t, _mm256_set1_ps(0x1.000004p+0f), _mm256_set1_ps(0x1.000004p-126f));
