    const __m256 c0_m0_zb0_th_t0 = _mm256_sub_ps(c0_m0_zb0_th, c0_m0_zb0_th_bb);
    const __m256 c0_m0_zb0_th_t1 = _mm256_sub_ps(c0_m0_h1, c0_m0_zb0_th_t0);
    const __m256 c0_m0_zb0_th_t2 = _mm256_sub_ps(c0_m0_nm1, c0_m0_zb0_th_bb);
