    const __m256 c0_m0_zb0_c = _mm256_add_ps(c0_m0_zb0_sl, c0_m0_zb0_th);
    // (c0_m0_zb0_vh, c0_m0_zb0_vl) = fast_two_sum(c0_m0_zb0_sh, c0_m0_zb0_c)
