    const __m256 c0_m0_zb0_vh_z = _mm256_sub_ps(c0_m0_zb0_vh, c0_m0_zb0_sh);
    const __m256 c0_m0_zb0_vl = _mm256_sub_ps(c0_m0_zb0_c, c0_m0_zb0_vh_z);
    const __m256 c0_m0_zb0_w = _mm256_add_ps(c0_m0_zb0_tl, c0_m0_zb0_vl);
