    const __m256 c0_m0_zb0 = _mm256_add_ps(c0_m0_zb0_vh, c0_m0_zb0_w);
    const __m256 c0_m0_zb0_z = _mm256_sub_ps(c0_m0_zb0, c0_m0_zb0_vh);
    const __m256 c0_m0_zb1 = _mm256_sub_ps(c0_m0_zb0_w, c0_m0_zb0_z);
    const __m256 c0_m0_zb0_az = _mm256_andnot_ps(_mm256_set1_ps(-0.0f), c0_m0_zb0);
    const __m256 c0_m0_zb0_t = _mm256_fmadd_ps(c0_m0_zb0_az, _mm256_set1_ps(0x1.800008p-47f), _mm256_setzero_ps());
    const __m256 c0_m0_eb = _mm256_fmadd_ps(c0_m0_zb0_t, _mm256_set1_ps(0x1.000004p+0f), _mm256_set1_ps(0x1.000004p-126f));
