    const __m256 c0_m0_me1 = _mm256_blendv_ps(c0_m0_md1, _mm256_setzero_ps(), c0_m0_mu);
    const __m256 c0_m0_bo = _mm256_and_ps(c0_m0_ml, c0_m0_mu);
    const __m256 c0_m0_mf0 = _mm256_blendv_ps(c0_m0_me0, _mm256_setzero_ps(), c0_m0_bo);
    const __m256 c0_m0_mf1 = _mm256_blendv_ps(c0_m0_me1, _mm256_setzero_ps(), c0_m0_bo);
    const __m256 c0_m0_un = _mm256_or_ps(c0_m0_ml, c0_m0_mu);
    const __m256 c0_m0_rd = _mm256_blendv_ps(c0_m0_rc, _mm256_set1_ps(std::numeric_limits<float>::infinity()), c0_m0_un);
    const __m256 c0_m0_ne = _mm256_cmp_ps(zl0, _mm256_set1_ps(std::numeric_limits<float>::infinity()), _CMP_LT_OQ);
    const __m256 c0_m0 = _mm256_blendv_ps(_mm256_set1_ps(std::numeric_limits<float>::quiet_NaN()), c0_m0_mf0, c0_m0_ne);
    const __m256 c0_m1 = _mm256_blendv_ps(_mm256_set1_ps(std::numeric_limits<float>::quiet_NaN()), c0_m0_mf1, c0_m0_ne);
    const __m256 r = _mm256_blendv_ps(_mm256_set1_ps(std::numeric_limits<float>::quiet_NaN()), c0_m0_rd, c0_m0_ne);
    const __m256 c0_un = _mm256_cmp_ps(r, _mm256_set1_ps(std::numeric_limits<float>::infinity()), _CMP_EQ_OQ);
    const __m256 c0 = _mm256_blendv_ps(c0_m0, _mm256_setzero_ps(), c0_un);
    const __m256 c1 = _mm256_blendv_ps(c0_m1, _mm256_setzero_ps(), c0_un);
    const __m256 wx = _mm256_cmp_ps(rx, _mm256_set1_ps(std::numeric_limits<float>::infinity()), _CMP_EQ_OQ);
    const __m256 nx = not_mask(wx);
    const __m256 wy = _mm256_cmp_ps(ry, _mm256_set1_ps(std::numeric_limits<float>::infinity()), _CMP_EQ_OQ);
    const __m256 ny = not_mask(wy);
    const __m256 ca0 = _mm256_blendv_ps(cx0, c0, ny);
    const __m256 ca1 = _mm256_blendv_ps(cx1, c1, ny);
    const __m256 ra = _mm256_blendv_ps(rx, r, ny);
    const __m256 cz0 = _mm256_blendv_ps(cy0, ca0, nx);
    const __m256 cz1 = _mm256_blendv_ps(cy1, ca1, nx);
    const __m256 rz = _mm256_blendv_ps(ry, ra, nx);
    cz0_out = cz0;
    cz1_out = cz1;
    rz_out = rz;
