    const __m256d t0_sl = _mm256_add_pd(t0_sh_t1, t0_sh_t2);
    const __m256d t0_v = _mm256_add_pd(s1, g1);
    const __m256d t0_w = _mm256_add_pd(t0_sl, t0_v);
    // (t0, t1) = fast_two_sum(t0_sh, t0_w)
