        const __m256 x0 = _mm256_loadu_ps(x0_in + i_);
        const __m256 x1 = _mm256_loadu_ps(x1_in + i_);
        const __m256 y0 = _mm256_loadu_ps(y0_in + i_);
        const __m256 y1 = _mm256_loadu_ps(y1_in + i_);
