        const __m256 step_z0_p0 = _mm256_add_ps(step_z0_p0_ch, step_z0_p0_cl3);
        const __m256 step_z0_p0_z = _mm256_sub_ps(step_z0_p0, step_z0_p0_ch);
        const __m256 step_z0_p1 = _mm256_sub_ps(step_z0_p0_cl3, step_z0_p0_z);
