        const __m256 chk_a = _mm256_andnot_ps(_mm256_set1_ps(-0.0f), step_z0);
        const __m256 chk_flag = _mm256_cmp_ps(chk_a, _mm256_set1_ps(std::numeric_limits<float>::infinity()), _CMP_LT_OQ);
